<?php
declare(strict_types=1);
session_start();
require __DIR__.'/bot.php';
if(empty($_SESSION['keddy_heartbeat_token']))$_SESSION['keddy_heartbeat_token']=bin2hex(random_bytes(24));
$heartbeatToken=$_SESSION['keddy_heartbeat_token'];$error='';$notice='';
if(isset($_GET['connected']))$notice='Your YouTube channel is connected. Keddy will speak as Keddy Bot BTS.';
if(isset($_GET['bot_connected']))$notice='Keddy Bot BTS is connected. Future streamer connections can use this same bot identity.';
if(isset($_GET['welcomed'])&&$_GET['welcomed']==='1')$notice='🤖 Keddy Bot BTS joined the live and sent the welcome message.';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$a=$_POST['action']??'';if($a==='start')startS();elseif($a==='stop')stopS();elseif($a==='next')nextS();elseif($a==='reconnect'){sv('oauth','');sv('oauth_channel_id','');sv('oauth_channel_title','');sv('chat_token','');sv('bot_welcome_live_id','');header('Location: oauth.php');exit;}elseif($a==='save'){
  sv('interval',(string)max(2,(int)$_POST['interval']));sv('duration',(string)max(2,(int)$_POST['duration']));
  $raw=preg_split('/\r\n|\r|\n/',trim((string)$_POST['tasks']));$raw=array_values(array_filter(array_map('trim',$raw)));if($raw)sj('tasks',$raw);
  $notice='Keddy settings saved.';
 }}catch(Throwable$e){$error=$e->getMessage();}}
$connected=!!gv('oauth');$botConnected=!!gv('bot_oauth');$connectedChannel=gv('oauth_channel_title');$ss=session();$tasks=tasks();
function h($x):string{return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
$lastSocial=(int)gv('social_timer_last','0');$socialLeft=max(0,KEDDY_SOCIAL_INTERVAL-(time()-$lastSocial));
?>
