<script>
let left=<?=$socialLeft?>;const el=document.getElementById('socialCountdown');function render(){const s=Math.max(0,left);el.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');left=Math.max(0,left-1);}render();setInterval(render,1000);
const active=<?= $ss['active']?'true':'false' ?>;if(active){const token=<?=json_encode($heartbeatToken)?>;const tick=()=>fetch('cron.php?heartbeat=1&token='+encodeURIComponent(token),{cache:'no-store'}).catch(()=>{});tick();setInterval(tick,30000);}
